class SummaryRanges {
    map<int, int> mp;

public:
    SummaryRanges() {}

    void addNum(int value) {
        auto it = mp.upper_bound(value);

        if (it != mp.begin() && prev(it)->second >= value)
            return;

        int l = value, r = value;

        if (it != mp.begin() && prev(it)->second + 1 == value) {
            l = prev(it)->first;
            mp.erase(prev(it));
        }

        if (it != mp.end() && it->first == value + 1) {
            r = it->second;
            mp.erase(it);
        }

        mp[l] = r;
    }

    vector<vector<int>> getIntervals() {
        vector<vector<int>> res;
        for (auto [l, r] : mp)
            res.push_back({l, r});
        return res;
    }
};

